-- ── State ─────────────────────────────────────────────────────────────────────
local reported         = {}
local server_locations = nil
local rom_ok           = nil       -- cached YES only
local mem              = {}
local log_fn           = nil

local function log(msg)
  if log_fn then pcall(log_fn, "[zelda2] " .. tostring(msg)) end
end

-- Pure-Lua bitwise AND: the connector runs on cores without bit32.
local function bit_and(a, b)
  local res, bitval = 0, 1
  while a > 0 and b > 0 do
    if a % 2 == 1 and b % 2 == 1 then res = res + bitval end
    a = math.floor(a / 2); b = math.floor(b / 2); bitval = bitval * 2
  end
  return res
end

-- ── Domain guard: a mistyped domain must fail LOUDLY, never fall back to
--    whichever domain the core happens to have current.
local _ap_domains, _ap_two_arg
local _ap_domain_warned = {}

local function ap_domain_ok(domain)
  if domain == nil then return true end
  if _ap_domains == nil and memory and memory.getmemorydomainlist then
    local ok, list = pcall(memory.getmemorydomainlist)
    if ok and type(list) == "table" then
      _ap_domains = {}
      for _, d in pairs(list) do _ap_domains[tostring(d)] = true end
      local reader = memory.read_u8 or memory.readbyte
      local probe = next(_ap_domains)
      if reader and probe ~= nil then
        _ap_two_arg = (pcall(reader, 0, probe)) and true or false
      end
    end
  end
  if _ap_domains == nil then return true end
  if _ap_domains[domain] then return true end
  if not _ap_domain_warned[domain] then
    _ap_domain_warned[domain] = true
    log("memory domain '" .. tostring(domain) .. "' does not exist in this core"
        .. " -- access refused (never redirected to the current domain)")
  end
  return false
end

local function resolve_memory_api()
  if not memory then return false end
  mem.read_u8 = memory.read_u8 or memory.readbyte
  return mem.read_u8 ~= nil
end

local function read_u8(addr, domain)
  if not mem.read_u8 then return nil end
  if not ap_domain_ok(domain) then return nil end
  local ok, v = pcall(mem.read_u8, addr, domain)
  if ok and type(v) == "number" then return v end
  if _ap_two_arg == false then
    if domain ~= nil and memory.usememorydomain
        and not pcall(memory.usememorydomain, domain) then return nil end
    ok, v = pcall(mem.read_u8, addr)
    if ok and type(v) == "number" then return v end
  end
  return nil
end

-- ── ROM identity. Only a YES is cached: a NO measured before the core has
--    mapped the cartridge must not stick for the rest of the session.
local function rom_is_zelda2()
  if rom_ok == true then return true end
  for i = 1, #ROM_SIG do
    local b = read_u8(ROM_SIG_ADDR + i - 1, PRGROM)
    if b == nil or b ~= ROM_SIG[i] then return false end
  end
  rom_ok = true
  log("ROM identity confirmed: Zelda II (USA)")
  return true
end

-- ── Gameplay gate: the three levels are 1-8 in a loaded game.
local function game_ready()
  local a = read_u8(ADDR_ATTACK, RAM)
  local m = read_u8(ADDR_MAGIC, RAM)
  local l = read_u8(ADDR_LIFE, RAM)
  if a == nil or m == nil or l == nil then return false end
  return a >= LEVEL_MIN and a <= LEVEL_MAX
     and m >= LEVEL_MIN and m <= LEVEL_MAX
     and l >= LEVEL_MIN and l <= LEVEL_MAX
end

local function load_locations(ids)
  if type(ids) ~= "table" then return end
  server_locations = {}
  local n = 0
  for _, id in ipairs(ids) do
    local v = tonumber(id)
    if v then server_locations[v] = true; n = n + 1 end
  end
  log("server location set: " .. n .. " ids")
end

local function wanted(ap_id)
  if server_locations == nil then return true end
  return server_locations[ap_id] == true
end

-- ── Contract ──────────────────────────────────────────────────────────────────
function M.init(ctx)
  if ctx and type(ctx.log) == "function" then log_fn = ctx.log end
  if not resolve_memory_api() then
    log("BizHawk memory API unavailable -- module idle")
    ADDRESSES_VERIFIED = false
    return
  end
  local cfg = (ctx and ctx.config) or {}
  load_locations(cfg.locations)
  log("ready: " .. #LOCATIONS .. " locations")
end

function M.poll()
  if not ADDRESSES_VERIFIED then return {} end
  if not rom_is_zelda2() then return {} end
  if not game_ready() then return {} end

  -- One pass over the whole block, mirroring the client's single bulk read.
  local presence = {}
  for off = 0, PRESENCE_LEN - 1 do
    local b = read_u8(PRESENCE_START + off, RAM)
    if b == nil then return {} end        -- a partial read proves nothing
    presence[off] = b
  end

  local new = {}
  for _, loc in ipairs(LOCATIONS) do
    if not reported[loc.id] and wanted(loc.id) then
      local b = presence[loc.addr - PRESENCE_START]
      -- INVERTED: the bit starts set and CLEARS on pickup.
      if b ~= nil and bit_and(b, loc.mask) == 0 then
        reported[loc.id] = true
        new[#new + 1] = loc.id
      end
    end
  end
  return new
end

function M.is_goal_complete()
  if not ADDRESSES_VERIFIED or not rom_is_zelda2() then return false end
  -- Behind the SAME gate as poll(): $076C is ordinary work RAM, and judging
  -- it before a save is loaded is how a seed completes itself at boot.
  if not game_ready() then return false end
  local r = read_u8(ADDR_ROUTINE, RAM)
  return r ~= nil and GOAL_VALUES[r] == true
end

-- Remote items: see the header. The player's own items are in the patched
-- ROM, so a solo seed needs no writes; delivering another world's item needs
-- a write path measured in a running game, and a wrong work-RAM write
-- corrupts the save. No-op rather than shipped unverified.
function M.receive_item(item_id, meta)
  -- intentionally empty (documented)
end

return M
